mapper.select:
SELECT TOP 1 * FROM material
WHERE drawing_no = #{drawingNo}
   OR specification = #{drawingNo}
ORDER BY id DESC

mapper.update:
UPDATE material
material_code = #{materialCode}, material_name = #{materialName}, specification = #{specification}, drawing_no = #{drawingNo}, material_type = #{materialType}, unit = #{unit}, weight = #{weight}, material_attr = #{materialAttr}, source = #{source}, erp_sync_time = #{erpSyncTime}, updated_at = GETDATE()
WHERE id = #{id}
